import pytest
import time
import json
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.common.action_chains import ActionChains
from selenium.webdriver.support import expected_conditions
from selenium.webdriver.support.wait import WebDriverWait
from selenium.webdriver.common.keys import Keys
from selenium.webdriver.common.desired_capabilities import DesiredCapabilities


class TestRegressaoSauceDemo():
  
  def setup_method(self, method):
    self.driver = webdriver.Chrome()
    self.vars = {}
  
  def teardown_method(self, method):
    self.driver.quit()
  
  def test_loginvalido(self):
    self.driver.get("https://www.saucedemo.com/")
    self.driver.set_window_size(1280, 800)
    self.driver.find_element(By.ID, "user-name").send_keys("standard_user")
    self.driver.find_element(By.CSS_SELECTOR, "[data-test=\"password\"]").send_keys("secret_sauce")
    self.driver.find_element(By.ID, "login-button").click()
    WebDriverWait(self.driver, 10).until(expected_conditions.visibility_of_element_located((By.CSS_SELECTOR, "[data-test=\"title\"]")))
    # oraculo: a pagina de produtos abriu
    assert self.driver.find_element(By.CSS_SELECTOR, "[data-test=\"title\"]").text == "Products"
    assert self.driver.title == "Swag Labs"
  
  def test_loginbloqueado(self):
    self.driver.get("https://www.saucedemo.com/")
    self.driver.set_window_size(1280, 800)
    self.driver.find_element(By.ID, "user-name").send_keys("locked_out_user")
    self.driver.find_element(By.CSS_SELECTOR, "[data-test=\"password\"]").send_keys("secret_sauce")
    self.driver.find_element(By.ID, "login-button").click()
    WebDriverWait(self.driver, 10).until(expected_conditions.visibility_of_element_located((By.CSS_SELECTOR, "[data-test=\"error\"]")))
    # teste negativo: o login deve ser recusado
    assert self.driver.find_element(By.CSS_SELECTOR, "[data-test=\"error\"]").text == "Epic sadface: Sorry, this user has been locked out."
    elements = self.driver.find_elements(By.CSS_SELECTOR, "[data-test=\"inventory-list\"]")
    assert len(elements) == 0
  
  def test_adicionaraocarrinho(self):
    # variaveis: troque aqui e o teste inteiro usa o novo valor
    self.vars["usuario"] = "standard_user"
    self.vars["senha"] = "secret_sauce"
    self.driver.get("https://www.saucedemo.com/")
    self.driver.set_window_size(1280, 800)
    self.driver.find_element(By.ID, "user-name").send_keys(str(self.vars["usuario"]))
    self.driver.find_element(By.CSS_SELECTOR, "[data-test=\"password\"]").send_keys(str(self.vars["senha"]))
    self.driver.find_element(By.ID, "login-button").click()
    WebDriverWait(self.driver, 10).until(expected_conditions.visibility_of_element_located((By.CSS_SELECTOR, "[data-test=\"inventory-list\"]")))
    # guarda o nome do 1o produto
    self.vars["produto"] = self.driver.find_element(By.CSS_SELECTOR, "[data-test=\"inventory-item-name\"]").text
    print("Produto escolhido: " + str(self.vars["produto"]))
    self.driver.find_element(By.CSS_SELECTOR, "[data-test^=\"add-to-cart\"]").click()
    assert self.driver.find_element(By.CSS_SELECTOR, "[data-test=\"shopping-cart-badge\"]").text == "1"
    self.driver.find_element(By.CSS_SELECTOR, "[data-test=\"shopping-cart-link\"]").click()
    WebDriverWait(self.driver, 10).until(expected_conditions.visibility_of_element_located((By.CSS_SELECTOR, "[data-test=\"cart-list\"]")))
    # o item no carrinho e o mesmo que foi adicionado
    assert self.driver.find_element(By.CSS_SELECTOR, "[data-test=\"inventory-item-name\"]").text == str(self.vars["produto"])
  
